module aes_key_mem;

  input wire [255:0] key;
  input wire [3:0] keylen;
  input wire init;
  output wire [255:0] key_mem;
  output wire ready;

  reg [255:0] key_mem_reg;
  reg ready_reg;

  always @(posedge clk or posedge rst_n)
    if (!rst_n)
      begin
        key_mem_reg <= 256'b0;
        ready_reg <= 1'b0;
      end
    else if (init)
      begin
        key_mem_reg <= key;
        ready_reg <= 1'b1;
      end

  assign key_mem = key_mem_reg;
  assign ready = ready_reg;

endmodule
